import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import { OBJLoader } from 'three/examples/jsm/loaders/OBJLoader';
import * as THREE from 'three';
import './App.css'; // Import the CSS file

// ModelLoader component that takes the model path as a prop
const ModelLoader = ({ modelPath }) => {
  const [model, setModel] = useState(null);
  const groupRef = useRef(null);

  useEffect(() => {
    const loader = new OBJLoader();
    const newModelRef = new THREE.Group();

    loader.load(
      modelPath,
      (obj) => {
        if (model) {
          model.traverse((child) => {
            if (child.isMesh) {
              child.geometry.dispose();
              if (child.material.isMaterial) {
                child.material.dispose();
              }
            }
          });
        }

        const box = new THREE.Box3().setFromObject(obj);
        const size = box.getSize(new THREE.Vector3());
        const maxDimension = Math.max(size.x, size.y, size.z);
        obj.rotation.x = -Math.PI / 2;
        const scaleFactor = 2.5 / maxDimension;
        obj.scale.set(scaleFactor, scaleFactor, scaleFactor);

        box.setFromObject(obj);
        const center = box.getCenter(new THREE.Vector3());
        obj.position.sub(center);

        obj.traverse((child) => {
          if (child.isMesh) {
            const edges = new THREE.EdgesGeometry(child.geometry, 45);
            const lineMaterial = new THREE.LineBasicMaterial({
              color: 0xffffff,
              opacity: 0.5,
              transparent: true,
            });
            const edgeLines = new THREE.LineSegments(edges, lineMaterial);
            edgeLines.position.copy(child.position);
            edgeLines.rotation.copy(child.rotation);
            edgeLines.scale.copy(child.scale);
            child.parent.add(edgeLines);
            child.parent.remove(child);
          }
        });

        newModelRef.add(obj);
        setModel(newModelRef);
      },
      undefined,
      (error) => console.error('Error loading OBJ:', error)
    );

    return () => {
      if (model) {
        model.traverse((child) => {
          if (child.isMesh) {
            child.geometry.dispose();
            if (child.material.isMaterial) {
              child.material.dispose();
            }
          }
        });
      }
    };
  }, [model, modelPath]); // Include `model` and `modelPath`

  useFrame(() => {
    if (groupRef.current) {
      groupRef.current.rotation.y += 0.003;
    }
  });

  return (
    <group ref={groupRef}>
      {!model && (
        <mesh>
          <boxGeometry args={[1, 1, 1]} />
          <meshBasicMaterial color="white" wireframe={true} />
        </mesh>
      )}
      {model && <primitive object={model} />}
    </group>
  );
};

const App = () => {
  const [models, setModels] = useState([]); // To store models list from the JSON
  const [selectedModel, setSelectedModel] = useState(null);
  const [highlightedModel, setHighlightedModel] = useState(null);
  const [asciiArt, setAsciiArt] = useState(""); // State for ASCII art
  const [asciiIndex, setAsciiIndex] = useState(0); // Index to track current character in the ASCII art

  // Load models from the JSON file
  useEffect(() => {
    fetch('./models.json')
      .then((response) => response.json())
      .then((data) => {
        setModels(data);
        setSelectedModel(data[0]?.file); // Set default model as the first in the list
      })
      .catch((error) => console.error('Error loading models:', error));
  }, []);

  // ASCII art string to display
  const asciiArtString = `
    Hello, world! This is ASCII art. Welcome to the 3D model viewer. Enjoy exploring models and more features.
    This art will break after 62 characters per line to fit the screen size.
    The next line should also follow this rule.
    Have fun with your project!
  `;

  // Function to break the ASCII art string into lines of 62 characters
  const breakAsciiIntoLines = (artString, maxLength) => {
    const lines = [];
    for (let i = 0; i < artString.length; i += maxLength) {
      lines.push(artString.slice(i, i + maxLength));
    }
    return lines.join('\n');
  };

  // Handle ASCII art printing
  useEffect(() => {
    const asciiWithLineBreaks = breakAsciiIntoLines(asciiArtString, 62);

    if (asciiIndex < asciiWithLineBreaks.length) {
      const interval = setInterval(() => {
        setAsciiArt((prev) => prev + asciiWithLineBreaks[asciiIndex]);
        setAsciiIndex((prev) => prev + 1);
      }, 30); // 30ms interval for each character

      return () => clearInterval(interval); // Cleanup the interval when the component unmounts
    }
  }, [asciiIndex]);

  const handleKeyPress = useCallback(
    (event) => {
      const currentIndex = models.findIndex((model) => model.file === selectedModel);
      if (event.key === 'ArrowDown') {
        const nextIndex = (currentIndex + 1) % models.length;
        setSelectedModel(models[nextIndex]?.file);
      } else if (event.key === 'ArrowUp') {
        const prevIndex = (currentIndex - 1 + models.length) % models.length;
        setSelectedModel(models[prevIndex]?.file);
      }
    },
    [models, selectedModel]
  );

  useEffect(() => {
    window.addEventListener('keydown', handleKeyPress);
    return () => {
      window.removeEventListener('keydown', handleKeyPress);
    };
  }, [handleKeyPress]);

  const handleModelClick = (model) => {
    setSelectedModel(model.file);
  };

  return (
    <div className="container">
      {/* Left Sidebar */}
      <div className="sidebar">
        <h3>Select a Model</h3>
        <ul>
          {models.map((model) => (
            <li
              key={model.file}
              className={`${selectedModel === model.file ? 'selected' : ''} ${highlightedModel === model.file ? 'highlighted' : ''}`}
              onClick={() => handleModelClick(model)}
              onMouseEnter={() => setHighlightedModel(model.file)}
              onMouseLeave={() => setHighlightedModel(null)}
            >
              {selectedModel === model.file ? `> ${model.name}` : model.name}
            </li>
          ))}
        </ul>
      </div>

      {/* Right Canvas and ASCII Art Container */}
      <div className="right-container">
        {/* ASCII Art display within the 'art' div */}
        <div className="ascii-art">
          {asciiArt}
        </div>

        <Canvas
          className="canvas"
          camera={{
            position: [2.5, 2.5, 2.5],
            fov: 45,
          }}
        >
          <ambientLight intensity={0.5} />
          <spotLight position={[10, 10, 10]} intensity={1} />
          <directionalLight position={[5, 5, 5]} intensity={1} />
          {/* Load model from the public folder */}
          {selectedModel && <ModelLoader modelPath={`./stls/${selectedModel}`} />}
          <OrbitControls
            enableZoom={false}
            minPolarAngle={Math.PI / 4}
            maxPolarAngle={Math.PI / 4}
            minAzimuthAngle={-Math.PI / 4}
            maxAzimuthAngle={Math.PI / 4}
          />
        </Canvas>
      </div>
    </div>
  );
};

export default App;


